/** What a tab says on its port: its hello first, then its asks, `bye` when it lets the core go. */
export type FromTab =
  | {
      say: 'hello';
      /** The page's `Start`, as JSON: read only when this tab is the first. */
      start: string;
      /** What the core's next dial carries. */
      credential: string;
      /** The name of the Web Lock the tab holds while it is open. */
      lock: string;
    }
  | {
      say: 'ask';
      ask: Ask;
    }
  | { say: 'bye' };

/**
 * A model's key for a row: the server's id of its record, as text (an event's number too). A model of one record
 * holds it under the empty key.
 */
export type Key = string;

/** Names a shell's call, so its answer finds it. */
export type Ticket = number;

